@MainActor class ObjectCaptureSession
init()
@MainActor static var isSupported: Bool { get }

@MainActor func start(imagesDirectory: URL, configuration: ObjectCaptureSession.Configuration = Configuration())
struct ObjectCaptureSession.Configuration { init(); var checkpointDirectory: URL?; var isOverCaptureEnabled: Bool }
@MainActor var configuration: ObjectCaptureSession.Configuration { get }

enum ObjectCaptureSession.CaptureState { case initializing; case ready; case detecting; case capturing; case finishing; case completed; case failed(any Error) }
@MainActor var state: ObjectCaptureSession.CaptureState { get }
@MainActor var stateUpdates: ObjectCaptureSession.Updates<ObjectCaptureSession.CaptureState> { get }

@MainActor func startDetecting() -> Bool
@discardableResult @MainActor func resetDetection() -> Bool
@MainActor func startCapturing()
@MainActor func finish()
@MainActor func cancel()
@MainActor func pause()
@MainActor func resume()
@MainActor var isPaused: Bool { get }
@MainActor var isPausedUpdates: ObjectCaptureSession.Updates<Bool> { get }

@MainActor func beginNewScanPassAfterFlip()
@MainActor func beginNewScanPass()
@MainActor var userCompletedScanPass: Bool { get }
@MainActor var userCompletedScanPassUpdates: ObjectCaptureSession.Updates<Bool> { get }

@MainActor func requestImageCapture()
@MainActor var canRequestImageCapture: Bool { get }
@MainActor var canRequestImageCaptureUpdates: ObjectCaptureSession.Updates<Bool> { get }
@MainActor var isAutoCaptureEnabled: Bool { get set }   // iOS 18.0+
@MainActor var numberOfShotsTaken: Int { get }
@MainActor var numberOfShotsTakenUpdates: ObjectCaptureSession.Updates<Int> { get }
@MainActor var maximumNumberOfInputImages: Int { get }
@MainActor var shouldPlayHaptics: Bool { get set }

@MainActor var feedback: Set<ObjectCaptureSession.Feedback> { get }
@MainActor var feedbackUpdates: ObjectCaptureSession.Updates<Set<ObjectCaptureSession.Feedback>> { get }
enum ObjectCaptureSession.Feedback { case environmentLowLight; case environmentTooDark; case movingTooFast; case objectNotDetected; case objectNotFlippable; case objectTooClose; case objectTooFar; case outOfFieldOfView; case overCapturing }
@MainActor var cameraTracking: ObjectCaptureSession.Tracking { get }
@MainActor var cameraTrackingUpdates: ObjectCaptureSession.Updates<ObjectCaptureSession.Tracking> { get }
enum ObjectCaptureSession.Tracking { case normal; case notAvailable; case limited(reason: ObjectCaptureSession.Tracking.Reason) }
enum ObjectCaptureSession.Tracking.Reason { case excessiveMotion; case initializing; case insufficientFeatures; case relocalizing }

@MainActor @preconcurrency struct ObjectCaptureView<Overlay> where Overlay : View
init(session: ObjectCaptureSession)
nonisolated init(session: ObjectCaptureSession, @ViewBuilder cameraFeedOverlay: () -> Overlay)
@MainActor @preconcurrency func hideObjectReticle(_ value: Bool = true) -> ObjectCaptureView<Overlay>   // iOS 18.0+

@MainActor struct ObjectCapturePointCloudView
init(session: ObjectCaptureSession)
@MainActor func showShotLocations(_ value: Bool = true) -> ObjectCapturePointCloudView   // iOS 18.0+

class PhotogrammetrySession
static var isSupported: Bool { get }
convenience init(input: URL, configuration: PhotogrammetrySession.Configuration = Configuration()) throws
convenience init<S>(input: S, configuration: PhotogrammetrySession.Configuration = Configuration()) throws where S : Sequence, S.Element == PhotogrammetrySample
var configuration: PhotogrammetrySession.Configuration { get }
var isProcessing: Bool { get }
var activeRequests: [PhotogrammetrySession.Request] { get }
var outputs: PhotogrammetrySession.Outputs { get }
func process(requests: [PhotogrammetrySession.Request]) throws
func cancel()
static let limits: PhotogrammetrySession.Limits
struct PhotogrammetrySession.Limits { var maximumInputImageDimension: Int; var maximumNumberOfInputImages: Int }

enum PhotogrammetrySession.Request {
  case modelFile(url: URL, detail: PhotogrammetrySession.Request.Detail = .reduced, geometry: PhotogrammetrySession.Request.Geometry? = nil)
  case modelEntity(detail: PhotogrammetrySession.Request.Detail = .reduced, geometry: PhotogrammetrySession.Request.Geometry? = nil)
  case bounds
  case pointCloud
  case poses
  init(modelFile: URL)
}
struct PhotogrammetrySession.Request.Geometry { init(bounds: BoundingBox, transform: Transform); init(orientedBounds: OrientedBoundingBox, transform: Transform); var bounds: BoundingBox; var transform: Transform; var orientedBounds: OrientedBoundingBox }
enum PhotogrammetrySession.Result { case modelFile(URL); case modelEntity(ModelEntity); case bounds(BoundingBox); case pointCloud(PhotogrammetrySession.PointCloud); case poses(PhotogrammetrySession.Poses) }

struct PhotogrammetrySession.Configuration {
  init()
  init(checkpointDirectory: URL)
  var isObjectMaskingEnabled: Bool
  var sampleOrdering: PhotogrammetrySession.Configuration.SampleOrdering
  var featureSensitivity: PhotogrammetrySession.Configuration.FeatureSensitivity
  var checkpointDirectory: URL?          // iOS 17 / macOS 14
  var ignoreBoundingBox: Bool            // iOS 18.0+ / macOS 15
  var customDetailSpecification: ... // macOS 14+ only
  var meshPrimitive: ...               // macOS 15+ only
}
enum SampleOrdering { case unordered; case sequential }
enum FeatureSensitivity { case normal; case high }

struct PhotogrammetrySession.Outputs : AsyncSequence { func makeAsyncIterator() -> PhotogrammetrySession.Outputs.Iterator; typealias Element = PhotogrammetrySession.Output }
enum PhotogrammetrySession.Output : Sendable {
  case inputComplete
  case requestProgress(PhotogrammetrySession.Request, fractionComplete: Double)
  case requestProgressInfo(PhotogrammetrySession.Request, PhotogrammetrySession.Output.ProgressInfo)
  case requestComplete(PhotogrammetrySession.Request, PhotogrammetrySession.Result)
  case requestError(PhotogrammetrySession.Request, any Error)
  case processingComplete
  case processingCancelled
  case invalidSample(id: Int, reason: String)
  case skippedSample(id: Int)
  case automaticDownsampling
  case stitchingIncomplete
  var localizedDescription: String { get }
}
struct PhotogrammetrySession.Output.ProgressInfo { let estimatedRemainingTime: TimeInterval?; let processingStage: PhotogrammetrySession.Output.ProcessingStage? }
enum PhotogrammetrySession.Output.ProcessingStage { case preProcessing; case imageAlignment; case pointCloudGeneration; case meshGeneration; case textureMapping; case optimization }
